const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const repo = new DocumentRepository([{ id: 'one', tenant: 'a', owner: 'u', deleted: false, archived: false }]);
const service = new DocumentService(repo);
const admin = { tenant: 'a', user: 'u', role: 'admin' };
service.archive(admin, 'one');
assert.equal(repo.documents[0].archived, true);
service.archive(admin, 'one');
assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
assert.throws(() => service.archive(admin, 'missing'), /^Error: not found$/);

// Cover visibility, ownership and permissions for both new and repeated archives.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const owner of ['u', 'other']) {
    for (const archived of [false, true]) {
      for (const visibility of ['visible', 'missing', 'deleted', 'foreign', 'foreign-deleted']) {
        const document = {
          id: 'target',
          tenant: visibility.startsWith('foreign') ? 'b' : 'a',
          owner,
          deleted: visibility.includes('deleted'),
          archived,
        };
        const untouched = { id: 'untouched', tenant: 'a', owner: 'u', deleted: false, archived: false };
        const documents = visibility === 'missing' ? [untouched] : [document, untouched];
        const repository = new DocumentRepository(documents);
        repository.audit.push({ actor: 'previous', document: 'previous-document' });
        const beforeDocuments = structuredClone(repository.documents);
        const beforeAudit = structuredClone(repository.audit);
        const actor = { tenant: 'a', user: 'u', role };
        const subject = new DocumentService(repository);
        const permitted = role === 'admin' || (role === 'editor' && owner === actor.user);
        const error = visibility !== 'visible' ? 'not found' : permitted ? undefined : 'forbidden';

        if (error) {
          assert.throws(() => subject.archive(actor, 'target'), { name: 'Error', message: error });
          assert.deepEqual(repository.documents, beforeDocuments);
          assert.deepEqual(repository.audit, beforeAudit);
        } else {
          subject.archive(actor, 'target');
          const expectedDocuments = structuredClone(beforeDocuments);
          expectedDocuments[0].archived = true;
          assert.deepEqual(repository.documents, expectedDocuments);
          assert.deepEqual(repository.audit, archived ? beforeAudit : [
            ...beforeAudit, { actor: actor.user, document: 'target' },
          ]);
          const afterAudit = structuredClone(repository.audit);
          subject.archive(actor, 'target');
          assert.deepEqual(repository.documents, expectedDocuments);
          assert.deepEqual(repository.audit, afterAudit);
        }
      }
    }
  }
}
EOF
